```javascript
// ko-debug.js

function levenshteinDistance(str1, str2) {
  const m = str1.length;
  const n = str2.length;

  // Create a matrix
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

  // Initialize
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],      // deletion
          dp[i][j - 1],      // insertion
          dp[i - 1][j - 1]   // substitution
        );
      }
    }
  }

  return dp[m][n];
}

function createDebugHelper(viewModel) {
  const getAvailableProperties = () => {
    return Object.keys(viewModel || {}).sort();
  };

  return {
    diagnoseMissingProperty: function(propertyName) {
      const availableProperties = getAvailableProperties();

      // Find closest match
      let suggestion = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const distance = levenshteinDistance(propertyName, prop);
        if (distance <= 3) {
          if (distance < minDistance) {
            minDistance = distance;
            suggestion = prop;
          } else if (distance === minDistance) {
            // If tie, return alphabetically first
            if (prop < suggestion) {
              suggestion = prop;
            }
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion
      };
    }
  };
}

module.exports = {
  createDebugHelper,
  // Also export levenshteinDistance so it can be used in tests if needed
  levenshteinDistance
};
```

